/* Minimal config.h for libopus 1.5.2 built into DiPlay for Android (arm64/armv7/x86_64).
 * Generated by hand instead of autotools: libopus only needs the feature macros below in
 * the FIXED_POINT path we compile. The full autoconf config would also set PACKAGE_* and
 * feature guards that are unused by the fixed-point encoder/decoder. */

#ifndef OPUS_ANDROID_CONFIG_H
#define OPUS_ANDROID_CONFIG_H

#define PACKAGE_VERSION "1.5.2"

/* Fixed-point build: no FPU-dependent float paths. */
#define FIXED_POINT 1
#define DISABLE_FLOAT_API 1

/* arm64 / armv7 / x86_64 all provide lrintf and lrint via libm. */
#define HAVE_LRINT 1
#define HAVE_LRINTF 1

/* Android NDK provides alloca.h on all supported ABIs. */
#define HAVE_ALLOCA_H 1

/* Variable-length arrays are supported by clang/gcc on all our ABIs. */
#define VAR_ARRAYS 1

/* We do not use the runtime CPU dispatch (no SSE/NEON intrinsics in the fixed-point path). */
#define HAVE_RTCD 0

#endif /* OPUS_ANDROID_CONFIG_H */
